1	/**
2	 * Stripe webhook receiver (Phase 3).
3	 *
4	 * Local invoice state is fully driven by Stripe events. We never optimistically
5	 * mark a row paid from the UI — every status flip lands here through a signed
6	 * Stripe POST. The only escape hatch is `markInvoicePaidManually` for cash/wire.
7	 *
8	 * Events handled:
9	 *   invoice.paid           → status='paid',   paid_at=now()   (+ client receipt email)
10	 *   invoice.payment_failed → status='failed'                  (+ admin notification email)
11	 *   invoice.finalized      → mirror hosted_invoice_url        (re-finalization can change it)
12	 *   invoice.voided         → status='void'
13	 *
14	 * Everything else is acked with `200 { received: true, ignored }` so Stripe
15	 * stops retrying — Stripe expects 2xx for "received and acknowledged", not
16	 * "acted on".
17	 *
18	 * Idempotency: webhook delivery is at-least-once. We dedupe per `event.id`
19	 * with a small in-memory LRU (good enough for serverless single-region) AND
20	 * the underlying UPDATE is naturally idempotent (mirror-of-target-state).
21	 *
22	 * Runtime constraint: nodejs (Stripe SDK does not run on edge).
23	 */
24	import { NextResponse } from "next/server";
25	import { createAdminClient } from "@/lib/supabase/server";
26	import { verifyWebhookSignature } from "@/lib/stripe";
27	import { forgetStripeEvent, rememberStripeEvent } from "@/lib/stripe-event-dedupe";
28	import { sendEmail } from "@/lib/resend";
29	import {
30	  invoicePaidToClient,
31	  invoicePaymentFailedToAdmin
32	} from "@/lib/resend-templates";
33	import type Stripe from "stripe";
34	
35	export const runtime = "nodejs";
36	export const dynamic = "force-dynamic";
37	
