39	  process.env.RESEND_REPLY_TO ?? "jeremyw@dobeu.net";
40	
41	interface InvoiceRow {
42	  id: string;
43	  project_id: string;
44	  amount_cents: number;
45	  currency: string | null;
46	  status: string;
47	}
48	
49	export async function POST(request: Request): Promise<NextResponse> {
50	  const startedAt = Date.now();
51	  const requestId = request.headers.get("stripe-request-id") ?? crypto.randomUUID();
52	
53	  console.log(
54	    JSON.stringify({
55	      msg: "stripe_webhook_received",
56	      request_id: requestId,
57	      ts: new Date().toISOString()
58	    })
59	  );
60	
61	  const rawBody = await request.text();
62	  const sig = request.headers.get("stripe-signature");
63	
64	  let event: Stripe.Event;
65	  try {
66	    event = verifyWebhookSignature(rawBody, sig);
67	  } catch (e) {
68	    console.warn(
69	      JSON.stringify({
70	        msg: "stripe_webhook_invalid_signature",
71	        request_id: requestId,
72	        error: e instanceof Error ? e.message : String(e)
73	      })
74	    );
75	    return NextResponse.json({ ok: false, error: "invalid_signature" }, { status: 400 });
76	  }
77	
78	  if (rememberStripeEvent(event.id)) {
79	    console.log(
80	      JSON.stringify({
81	        msg: "stripe_webhook_duplicate",
82	        request_id: requestId,
83	        event_id: event.id,
84	        event_type: event.type
85	      })
86	    );
87	    return NextResponse.json({ received: true, deduped: true });
88	  }
89	
90	  console.log(
91	    JSON.stringify({
92	      msg: "stripe_webhook_verified",
93	      request_id: requestId,
94	      event_id: event.id,
95	      event_type: event.type
96	    })
97	  );
98	
99	  const admin = createAdminClient();
100	
101	  try {
102	    switch (event.type) {
103	      case "invoice.paid": {
104	        const inv = event.data.object as Stripe.Invoice;
105	        if (inv.id) {
106	          const { data: row } = await admin
107	            .from("invoices")
108	            .update({ status: "paid", paid_at: new Date().toISOString() })
109	            .eq("stripe_invoice_id", inv.id)
110	            .select("id,project_id,amount_cents,currency,status")
111	            .single();
112	
113	          await notifyInvoicePaid(admin, inv, row as InvoiceRow | null);
114	        }
115	        break;
116	      }
117	
118	      case "invoice.payment_failed": {
119	        // Schema enum (invoice_status) doesn't have 'failed'/'uncollectible'
120	        // -- 'overdue' is the closest semantic match (invoice didn't get
121	        // paid). The admin email is the operational signal; the local row's
122	        // status just keeps the dashboard honest.
123	        const inv = event.data.object as Stripe.Invoice;
124	        if (inv.id) {
125	          const { data: row } = await admin
126	            .from("invoices")
127	            .update({ status: "overdue" })
128	            .eq("stripe_invoice_id", inv.id)
129	            .select("id,project_id,amount_cents,currency,status")
130	            .single();
131	
132	          await notifyInvoiceFailed(inv, row as InvoiceRow | null);
133	        }
134	        break;
135	      }
136	
137	      case "invoice.finalized": {
138	        const inv = event.data.object as Stripe.Invoice;
139	        if (inv.id && inv.hosted_invoice_url) {
