160	        console.log(
161	          JSON.stringify({
162	            msg: "stripe_webhook_ignored",
163	            request_id: requestId,
164	            event_id: event.id,
165	            event_type: event.type
166	          })
167	        );
168	        break;
169	    }
170	  } catch (e) {
171	    console.error(
172	      JSON.stringify({
173	        msg: "stripe_webhook_handler_error",
174	        request_id: requestId,
175	        event_id: event.id,
176	        event_type: event.type,
177	        error: e instanceof Error ? e.message : String(e)
178	      })
179	    );
180	    // Removing the event from the dedupe set lets Stripe retry. Errors are
181	    // worth retrying (transient DB, transient Resend) far more often than
182	    // they aren't.
183	    forgetStripeEvent(event.id);
184	    return NextResponse.json({ ok: false, error: "handler_error" }, { status: 500 });
185	  }
186	
187	  console.log(
188	    JSON.stringify({
189	      msg: "stripe_webhook_complete",
190	      request_id: requestId,
191	      event_id: event.id,
192	      event_type: event.type,
193	      duration_ms: Date.now() - startedAt
194	    })
195	  );
196	
197	  return NextResponse.json({ received: true });
198	}
