1	/**
2	 * Stripe webhook handler tests.
3	 *
4	 * Mocks lib/stripe (signature verify), lib/resend (email), and the admin
5	 * Supabase client. Exercises:
6	 *   - invalid signature → 400
7	 *   - duplicate event.id → 200 deduped (no DB writes)
8	 *   - invoice.paid       → updates row to paid + sends client receipt
9	 *   - invoice.payment_failed → updates row to uncollectible + sends admin alert
10	 *   - invoice.finalized  → mirrors hosted_invoice_url
11	 *   - invoice.voided     → status='void'
12	 *   - unknown event type → 200 ignored (no DB writes)
13	 *   - handler error      → 500 + event removed from dedupe so retry works
14	 */
15	import { describe, it, expect, beforeEach, vi } from "vitest";
16	
17	const h = vi.hoisted(() => {
18	  const verifyMock = vi.fn();
19	  const sendEmailMock = vi.fn(() => Promise.resolve({ ok: true }));
20	  const adminInvocations: Array<{
21	    table: string;
22	    op: string;
23	    payload?: unknown;
24	    where?: { col: string; val: string };
25	  }> = [];
26	  const adminBehavior = {
27	    updatedRow: null as null | {
28	      id: string;
29	      project_id: string;
30	      amount_cents: number;
31	      currency: string | null;
32	      status: string;
33	    },
34	    updateError: null as null | { message: string },
35	    throwOnUpdate: false
36	  };
37	  return { verifyMock, sendEmailMock, adminInvocations, adminBehavior };
38	});
39	
40	vi.mock("@/lib/stripe", () => ({
41	  verifyWebhookSignature: h.verifyMock
42	}));
43	
44	vi.mock("@/lib/resend", () => ({
45	  sendEmail: h.sendEmailMock,
46	  isResendConfigured: () => true
47	}));
48	
49	vi.mock("@/lib/supabase/server", () => ({
50	  createAdminClient: () => ({
51	    from: (table: string) => ({
52	      update: (payload: unknown) => ({
53	        eq: (col: string, val: string) => {
54	          h.adminInvocations.push({ table, op: "update", payload, where: { col, val } });
55	          const rejectIfNeeded = <T,>(value: T): Promise<T> =>
56	            h.adminBehavior.throwOnUpdate
57	              ? Promise.reject(new Error("db down"))
58	              : Promise.resolve(value);
59	          return {
60	            select: () => ({
61	              single: () =>
62	                rejectIfNeeded({
63	                  data: h.adminBehavior.updatedRow,
64	                  error: h.adminBehavior.updateError
65	                })
66	            }),
67	            then: (
68	              onF: (v: { data: null; error: { message: string } | null }) => unknown,
69	              onR?: (e: unknown) => unknown
70	            ) =>
71	              rejectIfNeeded({ data: null, error: h.adminBehavior.updateError }).then(onF, onR)
72	          };
73	        }
74	      })
75	    })
76	  }),
77	  createClient: vi.fn()
78	}));
79	
80	async function importRouteFresh() {
81	  vi.resetModules();
82	  const mod = await import("./route");
83	  const dedupe = await import("@/lib/stripe-event-dedupe");
84	  dedupe.__resetSeenStripeEventsForTests();
85	  return mod;
86	}
87	
88	beforeEach(() => {
89	  vi.clearAllMocks();
90	  h.adminInvocations.length = 0;
91	  h.adminBehavior.updatedRow = null;
92	  h.adminBehavior.updateError = null;
93	  h.adminBehavior.throwOnUpdate = false;
94	  process.env.STRIPE_SECRET_KEY = "sk_test_dummy";
95	  process.env.STRIPE_WEBHOOK_SECRET = "whsec_dummy";
96	});
97	
98	function makeRequest(body: string, sig: string | null = "t=1,v1=ok"): Request {
99	  const headers = new Headers();
100	  if (sig) headers.set("stripe-signature", sig);
101	  headers.set("stripe-request-id", "req_test_123");
102	  return new Request("https://dobeu.net/api/webhooks/stripe", {
103	    method: "POST",
104	    body,
105	    headers
106	  });
107	}
108	
109	describe("POST /api/webhooks/stripe", () => {
110	  it("returns 400 on invalid signature", async () => {
111	    h.verifyMock.mockImplementationOnce(() => {
112	      throw new Error("bad sig");
113	    });
114	    const { POST } = await importRouteFresh();
115	    const res = await POST(makeRequest("{}", "t=1,v1=bad"));
116	    expect(res.status).toBe(400);
117	    const json = await res.json();
118	    expect(json.error).toBe("invalid_signature");
119	    expect(h.adminInvocations).toHaveLength(0);
120	  });
121	
122	  it("returns 200 deduped on duplicate event.id without re-running handler", async () => {
123	    h.verifyMock.mockReturnValue({
124	      id: "evt_dup",
125	      type: "invoice.paid",
126	      data: { object: { id: "in_1", customer_email: "x@y.z" } }
127	    });
128	    h.adminBehavior.updatedRow = {
129	      id: "inv_1",
130	      project_id: "p_1",
131	      amount_cents: 5000,
132	      currency: "USD",
133	      status: "paid"
134	    };
135	    const { POST } = await importRouteFresh();
136	    const first = await POST(makeRequest("{}"));
137	    expect(first.status).toBe(200);
138	    const beforeCount = h.adminInvocations.length;
139	
140	    const second = await POST(makeRequest("{}"));
141	    expect(second.status).toBe(200);
142	    const body = await second.json();
143	    expect(body.deduped).toBe(true);
144	    expect(h.adminInvocations).toHaveLength(beforeCount);
145	  });
146	
147	  it("invoice.paid → updates row to paid + sends client receipt", async () => {
148	    h.verifyMock.mockReturnValue({
149	      id: "evt_paid",
150	      type: "invoice.paid",
151	      data: {
152	        object: {
153	          id: "in_paid_1",
154	          customer_email: "client@example.com",
155	          description: "Logo design"
156	        }
157	      }
158	    });
159	    h.adminBehavior.updatedRow = {
160	      id: "inv_77",
161	      project_id: "p_1",
162	      amount_cents: 12500,
163	      currency: "USD",
164	      status: "paid"
165	    };
166	    const { POST } = await importRouteFresh();
167	    const res = await POST(makeRequest("{}"));
168	    expect(res.status).toBe(200);
169	
170	    expect(h.adminInvocations).toHaveLength(1);
171	    expect(h.adminInvocations[0].table).toBe("invoices");
172	    expect(h.adminInvocations[0].payload).toMatchObject({ status: "paid" });
173	    expect(h.adminInvocations[0].where).toEqual({ col: "stripe_invoice_id", val: "in_paid_1" });
174	
175	    expect(h.sendEmailMock).toHaveBeenCalledTimes(1);
176	    expect(h.sendEmailMock).toHaveBeenCalledWith(
177	      expect.objectContaining({ to: "client@example.com" })
178	    );
179	  });
180	
181	  it("invoice.payment_failed → overdue + admin alert", async () => {
182	    h.verifyMock.mockReturnValue({
183	      id: "evt_failed",
184	      type: "invoice.payment_failed",
185	      data: {
